"""Build a self-contained local report from measured, immutable run artifacts."""
import datetime
import base64
import hashlib
import html
import json
import re
from pathlib import Path
from common import ROOT, read_jsonl, sha
from compare import grade


def main():
    runs = ROOT / 'runs'
    tests = read_jsonl(ROOT / 'seeds/test.jsonl')
    arms = {name: read_jsonl(runs / (name + '.jsonl')) for name in ['before', 'after', 'openbook']}
    for name, rows in arms.items():
        assert len(rows) == 9 and len({x['id'] for x in rows[1:]}) == 8
        assert rows[0]['meta']['closed_book'] is (name != 'openbook')
        assert rows[0]['meta']['exam_sha256'] == sha(ROOT / 'seeds/test.jsonl')
    for key in ['model_fingerprint', 'system_sha256', 'exam_sha256', 'versions', 'decoding']:
        assert arms['before'][0]['meta'][key] == arms['after'][0]['meta'][key] == arms['openbook'][0]['meta'][key]
    assert arms['before'][0]['meta']['adapter'] is None
    assert arms['after'][0]['meta']['adapter_sha256'] == sha(ROOT / 'adapters/lumen-v1/adapters.safetensors')
    assert arms['openbook'][0]['meta']['adapter'] is None
    freeze = json.loads((ROOT / 'provenance/primary-run-freeze.json').read_text())
    assert all(sha(ROOT / name) == digest for name, digest in freeze['files'].items()), 'Frozen primary artifact changed'
    resources = {name: json.loads((runs / 'resources' / (name + '.json')).read_text())
                 for name in ['calibration', 'calibration-17b', 'adapter-probe', 'baseline', 'train', 'after', 'openbook']}
    for name in ['calibration-17b', 'adapter-probe', 'baseline', 'train', 'after', 'openbook']:
        assert resources[name]['status'] == 'completed' and resources[name]['guard_exit_code'] == 0
    reviews = json.loads((runs / 'semantic-review.json').read_text())
    items = []
    for test in tests:
        obj = dict(test)
        obj['arms'] = {}
        for name, rows in arms.items():
            row = next(r for r in rows[1:] if r['id'] == test['id'])
            obj['arms'][name] = dict(row, auto_pass=bool(grade(row['raw'], test['gold'])))
        items.append(obj)
    scores = {name: sum(x['arms'][name]['auto_pass'] for x in items) for name in arms}
    train_job = next(json.loads(p.read_text()) for p in (ROOT / '.control/jobs').glob('*.json')
                     if json.loads(p.read_text())['stage'] == 'train')
    log = re.sub(r'\x1b\[[0-9;]*m', '', (ROOT / train_job['log']).read_text())
    losses = [{'iteration': int(n), 'loss': float(v)} for n, v in re.findall(r'^\s*(\d+)\s+val\s+([\d.]+)', log, re.M)]
    speeds = [float(s) for s in re.findall(r'^\s*\d+\s+[\d.]+\s*[▼▲]?\s+([\d.]+)\s+[\d.]+k', log, re.M)]
    model = json.loads((ROOT / 'model-lock.json').read_text())
    status = json.loads((runs / 'final-status.json').read_text())
    data = {'created_at': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'scores': scores,
            'items': items, 'resources': resources, 'semantic_review': reviews, 'losses': losses,
            'training_reported_tokens_per_second': speeds, 'model': model,
            'versions': arms['before'][0]['meta']['versions'], 'meta': {k: v[0]['meta'] for k, v in arms.items()},
            'adapter_bytes': (ROOT / 'adapters/lumen-v1/adapters.safetensors').stat().st_size,
            'status': status}
    (runs / 'results-data.json').write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
    serialized = json.dumps(data, ensure_ascii=False).replace('<', '\\u003c')
    logo = base64.b64encode((runs / 'video/dist/assets/tengu-wordmark-horizontal.svg').read_bytes()).decode()
    doc = TEMPLATE.replace('__DATA__', serialized).replace('__LOGO__', logo)
    (runs / 'report.html').write_text(doc)
    print(json.dumps({'scores': scores, 'report': str(runs / 'report.html'), 'checks': 'complete8, matched metadata, frozen files, completed guards'}, ensure_ascii=False))


